mapper.select:
select sum(s.quantity) quantity,
sum(s.mete_one) length,
sum(s.mete_one) netWeight, sum(s.mete_two) grossWeight,
m.`id` 'monomer.id', m.`name` 'monomer.name' from tech_product_summary s inner join plan_monomer m on m.id = s.monomer_id and m.bool_delete_enum = 0 where s.bool_delete_enum = 0 and s.project_id = #{projectId} and s.product_type = #{productType}
and s.category = #{category}
group by m.id,m.name

select s.quantity,
s.mete_one length,
s.mete_one netWeight, s.mete_two grossWeight,
d.`id` 'area.id', d.`name` 'area.name' from tech_product_summary s inner join plan_area d on d.id = s.monomer_id and d.bool_delete_enum = 0 where s.bool_delete_enum = 0 and s.monomer_id = #{monomerId} and s.product_type = #{productType}
and s.category = #{category}
order by d.sort,d.id
